// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        uint256 bounded = bound(amount, 0, 1 ether);
        vm.assume(actor != address(0));

        vm.deal(actor, bounded);

        bool ok;
        if (bounded == 0) {
            vm.prank(actor);
            try c.addToBalance{value: 0}() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(actor);
            try c.addToBalance{value: bounded}() {
                ok = true;
            } catch {
                ok = false;
            }
        }

        assertTrue(ok);
    }
}
